CREATE DATABASE apexplanet_task2;

USE apexplanet_task2;

select * from sales
order by Transaction_ID desc
limit 5 ;

SELECT COUNT(*) AS total_records
FROM sales_reimport;

SELECT *
FROM sales_reimport
LIMIT 10;

DESCRIBE sales_reimport;

-- Calculate sales performance for each product
SELECT
    Product,

    -- Calculate the total revenue generated by the product
    ROUND(SUM(Total_Sales), 2) AS Total_Sales,

    -- Calculate the total units sold
    SUM(Quantity) AS Total_Quantity,

    -- Count the number of unique transactions
    COUNT(DISTINCT Transaction_ID) AS Total_Transactions,

    -- Calculate the average sales value per transaction
    ROUND(AVG(Total_Sales), 2) AS Average_Sale

FROM sales_reimport

-- Combine records belonging to the same product
GROUP BY Product

-- Rank products from highest to lowest revenue
ORDER BY Total_Sales DESC;

-- Count the units sold for each product
SELECT
    Product,
    SUM(Quantity) AS Total_Quantity
FROM sales_reimport
GROUP BY Product

-- Display the products with the highest quantities first
ORDER BY Total_Quantity DESC;


-- Display individual transactions with sales greater than 300,000
SELECT
    Transaction_ID,
    Product,
    Category,
    Quantity,
    Unit_Price,
    Total_Sales
FROM sales_reimport

-- Filter individual rows before aggregation
WHERE Total_Sales > 300000

-- Show the highest-value transactions first
ORDER BY Total_Sales DESC;

-- Calculate sales performance for each category
SELECT
    Category,

    -- Calculate total revenue for each category
    ROUND(SUM(Total_Sales), 2) AS Total_Sales,

    -- Count the number of transactions in each category
    COUNT(DISTINCT Transaction_ID) AS Total_Transactions

FROM sales_reimport

-- Group transactions by category
GROUP BY Category

-- Keep only categories whose aggregated sales exceed 20 million
HAVING SUM(Total_Sales) > 20000000

-- Rank qualifying categories by revenue
ORDER BY Total_Sales DESC;

-- Analyze product performance using transactions above 100,000
SELECT
    Product,

    -- Calculate qualifying sales for each product
    ROUND(SUM(Total_Sales), 2) AS High_Value_Sales,

    -- Count qualifying transactions
    COUNT(*) AS Qualifying_Transactions

FROM sales_reimport

-- First, filter individual transactions
WHERE Total_Sales > 100000

-- Aggregate the filtered transactions by product
GROUP BY Product

-- Retain products with at least 10 qualifying transactions
HAVING COUNT(*) >= 10

-- Display the largest qualifying sales totals first
ORDER BY High_Value_Sales DESC;

-- Find products whose total sales exceed the average
-- total sales across all products

SELECT
    Product,
    ROUND(SUM(Total_Sales), 2) AS Total_Sales
FROM sales_reimport
GROUP BY Product

-- Compare each product's total against the average
-- of the six product-level totals
HAVING SUM(Total_Sales) > (
    SELECT AVG(product_total)
    FROM (
        SELECT SUM(Total_Sales) AS product_total
        FROM sales_reimport
        GROUP BY Product
    ) AS ProductTotals
)

-- Rank qualifying products from highest to lowest sales
ORDER BY Total_Sales DESC;

-- Create a temporary summary of customer purchasing activity
CREATE TEMPORARY TABLE customer_summary AS
SELECT
    Customer_ID,

    -- Get the customer's name
    MAX(Customer_Name) AS Customer_Name,

    -- Count unique transactions for each customer
    COUNT(DISTINCT Transaction_ID) AS Total_Transactions,

    -- Calculate total sales generated by the customer
    SUM(Total_Sales) AS Total_Sales

FROM sales_reimport

-- Group all records by customer
GROUP BY Customer_ID;

-- Join individual sales records with customer-level totals
SELECT
    s.Transaction_ID,
    s.Customer_ID,
    s.Customer_Name,
    s.Product,
    s.Total_Sales AS Transaction_Sales,

    -- Show the customer's overall sales total
    ROUND(c.Total_Sales, 2) AS Customer_Total_Sales,

    -- Show the customer's transaction count
    c.Total_Transactions

FROM sales_reimport AS s

-- Match each sales record to its customer summary
INNER JOIN customer_summary AS c
    ON s.Customer_ID = c.Customer_ID

-- Display the highest-value transactions first
ORDER BY s.Total_Sales DESC

-- Return only the first 10 records
LIMIT 10;

-- Find the top 10 customers by total sales
SELECT
    Customer_ID,

    -- Display the customer's name
    MAX(Customer_Name) AS Customer_Name,

    -- Calculate the customer's total sales
    ROUND(SUM(Total_Sales), 2) AS Customer_Total_Sales,

    -- Count unique transactions made by each customer
    COUNT(DISTINCT Transaction_ID) AS Total_Transactions

FROM sales_reimport

-- Aggregate sales at the customer level
GROUP BY Customer_ID

-- Rank customers by their total sales
ORDER BY Customer_Total_Sales DESC

-- Display only the top 10 customers
LIMIT 10;

-- Analyze monthly sales performance
SELECT
    -- Extract year and month from the order date
    DATE_FORMAT(Order_Date, '%Y-%m') AS Year_Month_,

    -- Calculate total sales for each month
    ROUND(SUM(Total_Sales), 2) AS Monthly_Sales,

    -- Count unique transactions in each month
    COUNT(DISTINCT Transaction_ID) AS Total_Transactions,

    -- Calculate the total quantity sold each month
    SUM(Quantity) AS Total_Quantity

FROM sales_reimport

-- Group transactions by year and month
GROUP BY DATE_FORMAT(Order_Date, '%Y-%m')

-- Display months chronologically
ORDER BY monthly_sales desc ;

-- Identify customer IDs associated with multiple names
SELECT
    Customer_ID,

    -- Count the distinct names assigned to each customer ID
    COUNT(DISTINCT Customer_Name) AS Name_Count,

    -- Display all different names found for that customer ID
    GROUP_CONCAT(
        DISTINCT Customer_Name
        ORDER BY Customer_Name
        SEPARATOR ', '
    ) AS Customer_Names

FROM sales_reimport

-- Group records belonging to the same customer ID
GROUP BY Customer_ID

-- Display only customer IDs with inconsistent names
HAVING COUNT(DISTINCT Customer_Name) > 1

-- Sort the results by customer ID
ORDER BY Customer_ID;

-- Count customer IDs that are associated with multiple names
SELECT
    COUNT(*) AS inconsistent_customer_ids
FROM (
    SELECT Customer_ID
    FROM sales_reimport

    -- Examine all records for each customer ID
    GROUP BY Customer_ID

    -- Keep IDs associated with more than one distinct name
    HAVING COUNT(DISTINCT Customer_Name) > 1
) AS InconsistentCustomers;

-- Count the total distinct customer IDs
SELECT
    COUNT(DISTINCT Customer_ID) AS total_customers
FROM sales_reimport;

-- Identify customer IDs associated with multiple names
WITH InconsistentCustomers AS (
    SELECT Customer_ID
    FROM sales_reimport
    GROUP BY Customer_ID
    HAVING COUNT(DISTINCT Customer_Name) > 1
)

-- Count the transactions associated with those customer IDs
SELECT
    COUNT(*) AS affected_transactions,
    COUNT(DISTINCT s.Customer_ID) AS affected_customer_ids,
    ROUND(
        100.0 * COUNT(*) /
        (SELECT COUNT(*) FROM sales_reimport),
        2
    ) AS affected_transaction_percentage
FROM sales_reimport AS s

-- Match transactions to the inconsistent customer IDs
INNER JOIN InconsistentCustomers AS i
    ON s.Customer_ID = i.Customer_ID;
    
-- Analyze sales performance across cities
SELECT
    City,

    -- Calculate total revenue generated in each city
    ROUND(SUM(Total_Sales), 2) AS Total_Sales,

    -- Calculate the total quantity sold in each city
    SUM(Quantity) AS Total_Quantity,

    -- Count unique transactions in each city
    COUNT(DISTINCT Transaction_ID) AS Total_Transactions,

    -- Calculate the average sales value per transaction
    ROUND(AVG(Total_Sales), 2) AS Average_Sale

FROM sales_reimport

-- Exclude missing city values from the city ranking
WHERE City IS NOT NULL

-- Combine records belonging to the same city
GROUP BY City

-- Rank cities from highest to lowest sales
ORDER BY Total_Sales DESC;

-- Analyze sales performance by customer age group
SELECT
    CASE
        WHEN Age BETWEEN 18 AND 25 THEN '18-25'
        WHEN Age BETWEEN 26 AND 35 THEN '26-35'
        WHEN Age BETWEEN 36 AND 45 THEN '36-45'
        WHEN Age BETWEEN 46 AND 55 THEN '46-55'
        WHEN Age >= 56 THEN '56+'
        ELSE 'Unknown'
    END AS Age_Group,

    -- Calculate total sales generated by each age group
    ROUND(SUM(Total_Sales), 2) AS Total_Sales,

    -- Count unique transactions for each age group
    COUNT(DISTINCT Transaction_ID) AS Total_Transactions,

    -- Calculate average sales per transaction
    ROUND(AVG(Total_Sales), 2) AS Average_Sale

FROM sales_reimport

-- Group transactions by the age ranges defined above
GROUP BY Age_Group

-- Rank age groups by total sales
ORDER BY Total_Sales DESC;

-- Compare total sales across categories and genders
SELECT
    Category,

    -- Calculate sales from female customers
    ROUND(
        SUM(CASE
            WHEN Gender = 'Female' THEN Total_Sales
            ELSE 0
        END), 2
    ) AS Female_Sales,

    -- Calculate sales from male customers
    ROUND(
        SUM(CASE
            WHEN Gender = 'Male' THEN Total_Sales
            ELSE 0
        END), 2
    ) AS Male_Sales,

    -- Calculate total sales across both genders
    ROUND(SUM(Total_Sales), 2) AS Total_Sales

FROM sales_reimport

-- Create one row per product category
GROUP BY Category

-- Rank categories by overall sales
ORDER BY Total_Sales DESC;

-- Calculate Pearson correlation between numerical columns
WITH CorrelationInputs AS (
    SELECT
        Quantity,
        Unit_Price,
        Total_Sales
    FROM sales_reimport
),

-- Calculate the correlation between Quantity and Total_Sales
QuantityCorrelation AS (
    SELECT
        (
            COUNT(*) * SUM(Quantity * Total_Sales)
            - SUM(Quantity) * SUM(Total_Sales)
        ) /
        NULLIF(
            SQRT(
                (
                    COUNT(*) * SUM(Quantity * Quantity)
                    - POW(SUM(Quantity), 2)
                ) *
                (
                    COUNT(*) * SUM(Total_Sales * Total_Sales)
                    - POW(SUM(Total_Sales), 2)
                )
            ),
            0
        ) AS Quantity_Sales_Correlation
    FROM CorrelationInputs
),

-- Calculate the correlation between Unit_Price and Total_Sales
PriceCorrelation AS (
    SELECT
        (
            COUNT(*) * SUM(Unit_Price * Total_Sales)
            - SUM(Unit_Price) * SUM(Total_Sales)
        ) /
        NULLIF(
            SQRT(
                (
                    COUNT(*) * SUM(Unit_Price * Unit_Price)
                    - POW(SUM(Unit_Price), 2)
                ) *
                (
                    COUNT(*) * SUM(Total_Sales * Total_Sales)
                    - POW(SUM(Total_Sales), 2)
                )
            ),
            0
        ) AS Price_Sales_Correlation
    FROM CorrelationInputs
)

-- Display the two correlation coefficients
SELECT
    ROUND(q.Quantity_Sales_Correlation, 4)
        AS Quantity_Sales_Correlation,
    ROUND(p.Price_Sales_Correlation, 4)
        AS Price_Sales_Correlation
FROM QuantityCorrelation AS q
CROSS JOIN PriceCorrelation AS p;